// Stub de CRM para os testes locais da ponte.
// Decide o codigo HTTP a partir do texto da mensagem recebida:
//   FALHA_PERMANENTE  -> 422 (o classificador trata como invalido, sem retry)
//   FALHA_TRANSITORIA -> 503 nas duas primeiras tentativas e 201 na terceira
//   qualquer outro     -> 201 (criado)
const memoria = $getWorkflowStaticData('global');
if (!memoria.tentativas) memoria.tentativas = {};

const entrada = $input.first().json;
const corpoRecebido = entrada.body || entrada;
const chave = String(corpoRecebido.chave_idempotencia || 'sem-chave');
const mensagem = String(corpoRecebido.mensagem || '');

let codigo = 201;
let corpo = {
  id_crm: 'CRM-' + chave.slice(0, 8),
  status: 'created',
  chave_idempotencia: chave,
};

if (mensagem.includes('FALHA_PERMANENTE')) {
  codigo = 422;
  corpo = { erro: 'payload rejeitado pelo CRM (stub)', campo: 'mensagem' };
} else if (mensagem.includes('FALHA_TRANSITORIA')) {
  const n = (memoria.tentativas[chave] || 0) + 1;
  memoria.tentativas[chave] = n;
  if (n <= 2) {
    codigo = 503;
    corpo = { erro: 'CRM indisponivel (stub)', tentativa_recebida: n };
  } else {
    corpo.recuperado_na_tentativa = n;
  }
}

return [{ json: { codigo, corpo } }];
